625 :         processedArgs.add(matcher.group(1));
626 : 
627 :         String value = matcher.group(2);
628 :         Matcher quotesMatcher = quotesPattern.matcher(value);
629 :         if (quotesMatcher.matches()) {
630 :           processedArgs.add(quotesMatcher.group(1));
631 :         } else {
632 :           processedArgs.add(value);
633 :         }
634 :       } else {
635 :         processedArgs.add(arg);
636 :       }
637 :     }
638 : 
639 :     return processedArgs;
640 :   }"

